script:
Workspace.log("🤖 Запуск сценария генерации спринта...");

const projectName = "Маркетинг";

// 1. Создаем корневую задачу
const rootRes = await Workspace.callTool("add_task_to_project", {
  projectTitle: projectName,
  taskTitle: "Запустить рекламу в соцсетях"
});
Workspace.log(rootRes);

if (rootRes.status === "success") {
  const rootId = rootRes.task.id;

  // 2. Создаем вложенную подзадачу первого уровня, передавая parentId
  const subRes1 = await Workspace.callTool("add_task_to_project", {
    projectTitle: projectName,
    taskTitle: "Подготовить графические креативы",
    parentId: rootId
  });
  Workspace.log(subRes1);

  // 3. Создаем еще одну подзадачу
  const subRes2 = await Workspace.callTool("add_task_to_project", {
    projectTitle: projectName,
    taskTitle: "Согласовать бюджет",
    parentId: rootId
  });
  Workspace.log(subRes2);

  // 4. Допустим, бюджет согласовали мгновенно — робот сам ставит чекбокс!
  if (subRes2.status === "success") {
     const updateRes = await Workspace.callTool("update_task_status", {
       projectTitle: projectName,
       taskId: subRes2.task.id,
       done: true
     });
     Workspace.log(updateRes);
  }
}
